        "content": "우리의 구원은 100% 하나님의 은혜입니다. 나의 선행이나 의로움, 종교적 열심이 0.001%도 기여할 수 없습니다.\n\n모든 것이 하나님의 거저 주시는 선물이기에 우리는 결코 교만할 수 없고, 또한 나의 연약함 때문에 낙심할 수도 없습니다. 하나님의 사랑은 나의 자격에 좌우되지 않는 영원하고 신실한 사랑이기 때문입니다.\n\n오늘도 값없이 베풀어주신 십자가 대속의 은혜를 깊이 묵상하며, 감사와 찬양으로 주께 영광을 돌립니다."
