        "content": "하루의 분주함을 잠시 내려놓고 골방으로 들어갑니다.\n\n골방은 세상의 소음을 차단하고 오직 하나님과 단둘이 만나는 거룩한 지성소입니다. 은밀한 중에 내 신음과 한숨, 눈물까지도 다 알고 계시는 하늘 아버지께서 우리의 기도를 듣고 계십니다.\n\n말을 많이 해야 들으시는 것이 아닙니다. 상하고 통회하는 가난한 심령으로 주님 앞에 나아갈 때, 주님은 당신의 따뜻한 품으로 우리를 안아주십니다. 기도의 골방에서 하늘의 위로와 평안을 누리십시오."
